package vn.alarm.pro;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.*;import org.json.*;
public class RingActivity extends Activity {public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);int id=getIntent().getIntExtra("id",-1);JSONObject o=Store.get(this,id);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER);l.setPadding(30,30,30,30);l.setBackgroundColor(0xff101b30);setContentView(l);ImageView img=new ImageView(this);img.setImageResource(vn.alarm.pro.R.drawable.icon);l.addView(img,new LinearLayout.LayoutParams(250,250));TextView t=new TextView(this);t.setText("ĐẾN GIỜ BÁO THỨC\n\n"+(o==null?"":o.optString("note")));t.setTextColor(0xffffd780);t.setTextSize(28);t.setGravity(17);l.addView(t);Button stop=new Button(this);stop.setText("Tắt báo thức");l.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,RingService.class));finish();});Button snooze=new Button(this);snooze.setText("Báo lại sau 10 phút");l.addView(snooze);snooze.setOnClickListener(v->{if(o!=null)Store.schedule(this,o,System.currentTimeMillis()+600000);stopService(new Intent(this,RingService.class));finish();});}}